// anchor 사용 설명
{anchor: "top"} // position 으로 설정한 위치가 마커의 중앙 상단에 위치합니다.
{anchor: "left"} // position 으로 설정한 위치가 마커의 좌측 중단에 위치합니다.

// 단일 값의 offset 사용 설명
{offset: 10, anchor: "top"} // 마커의 상단을 기준으로 10 픽셀 아래에 마커를 위치.
{offset: 10, anchor: "top-left"} // 마커의 좌측 상단을 기준으로 [10, 10] 픽셀 오른쪽 아래에 마커를 위치.

